export function productionWorkSeconds(recipe:ProductionRecipe,_workplace?:Pick<Building,'type'>){return PRODUCTION_RECIPES[recipe].workSeconds;}
export type ProductionRecipe=keyof typeof PRODUCTION_RECIPES;
const dryingRecipe=(r:ProductionRecipeSpec)=>r.preservation==='air'||r.preservation==='clay';
export type ProductionProject=import("./communityHandoverTypes").HandoverProvenance&{charcoal?:CharcoalBatch;brewing?:BrewBatch;curds?:CurdBatch;dairy?:DairyBatch;basketOrigin?:PotteryOrigin;practiceRecorded?:true;practiceWorkers?:{id:number;work:number}[];pauseCause?:'manual'|'interrupted';cacheExposure?:number;cacheAnchor?:{x:number;z:number;kind:"camp"|"building";id?:number};pottery?:{version:1;origin:PotteryOrigin;broken:number};id:number;team:number;recipe:ProductionRecipe;workplace:number;actorId:number|null;phase:'collecting'|'unloading'|'stored'|'carrying'|'working'|'curing'|'ready'|'returning'|'paused'|'complete'|'lost';resumePhase:'collecting'|'unloading'|'carrying'|'working'|'curing'|'ready'|'returning';drying?:DryingExposure;outputReadyAt?:number;pickupReviewAt?:number;progress:number;started:number;finished?:number;blockedReason:string};
export type ProductionState={version:1;projects:ProductionProject[];metrics:{consumed:ItemStock;produced:ItemStock;spoiled:ItemStock;lost:ItemStock;logsUsed:number;waterUsedLiters:number;grainUsed?:number;grainLost?:number;edibleFoodProduced?:number;edibleFoodLost?:number;foodInputsUsed?:Partial<Record<FoodKind,number>>;foodInputsLost?:Partial<Record<FoodKind,number>>;foodOutputsProduced?:Partial<Record<FoodKind,number>>;foodOutputsLost?:Partial<Record<FoodKind,number>>;dryingExposureSeconds?:number;wetExposureSeconds?:number;completed:number;interrupted:number}};
const sum=(items:ItemStock)=>Object.values(items).reduce((n,v)=>n+(v||0),0);
const add=(items:ItemStock,key:ItemKind,n:number)=>{items[key]=(items[key]||0)+n;};
function state(g:Game){return g.state.production??={version:1,projects:[],metrics:{consumed:{},produced:{},spoiled:{},lost:{},logsUsed:0,waterUsedLiters:0,grainUsed:0,grainLost:0,edibleFoodProduced:0,edibleFoodLost:0,foodInputsUsed:{},foodInputsLost:{},dryingExposureSeconds:0,wetExposureSeconds:0,completed:0,interrupted:0}} as ProductionState;}
export function productionEnabled(g:Game,team:number){return g.state.buildings.some(b=>b.team===team&&['hearth','dryrack','smokehouse'].includes(b.type)&&g.finished(b));}
/** Fresh games persist their rule; missing legacy rules need a real own station, not a terrain version. */
export function animalProcessingEnabled(g:Game,team:number){return g.tribe(team)?.animalProcessingVersion===1||productionEnabled(g,team);}
export function activateAnimalProcessing(g:Game,team:number){const t=g.tribe(team);if(!t||t.animalProcessingVersion===1||!productionEnabled(g,team))return false;t.animalProcessingVersion=1;return true;}
export function itemCapacity(g:Game,team:number){return PRODUCTION_RULES.baseItemCapacity+inheritedCacheCapacity(g,team)+g.state.buildings.filter(b=>b.team===team&&b.type==='warehouse'&&g.finished(b)).length*PRODUCTION_RULES.warehouseCapacity;}
export function storedItemUnits(g:Game,team:number){return packedItemStorageUnits(g.tribe(team).items||{})+armorStoredUnits(g,team)+seedReserveLiters(g.tribe(team).seeds||0)/INVENTORY_VOLUME_RULES.litersPerStorageUnit;}
function items(g:Game,team:number){return g.tribe(team).items??={};}
